mkuse!{use crate :: simd :: { LaneCount , Mask , MaskElement , Simd , SimdElement , SupportedLaneCount } ;}
mkitem!{mkimpl!{impl < T , const N : usize > Mask < T , N > where T : MaskElement , LaneCount < N > : SupportedLaneCount , { # [doc = " Choose elements from two vectors."] # [doc = ""] # [doc = " For each element in the mask, choose the corresponding element from `true_values` if"] # [doc = " that element mask is true, and `false_values` if that element mask is false."] # [doc = ""] # [doc = " # Examples"] # [doc = " ```"] # [doc = " # #![feature(portable_simd)]"] # [doc = " # use core::simd::{Simd, Mask};"] # [doc = " let a = Simd::from_array([0, 1, 2, 3]);"] # [doc = " let b = Simd::from_array([4, 5, 6, 7]);"] # [doc = " let mask = Mask::from_array([true, false, false, true]);"] # [doc = " let c = mask.select(a, b);"] # [doc = " assert_eq!(c.to_array(), [0, 5, 6, 3]);"] # [doc = " ```"] # [inline] # [must_use = "method returns a new vector and does not mutate the original inputs"] pub fn select < U > (self , true_values : Simd < U , N > , false_values : Simd < U , N >) -> Simd < U , N > where U : SimdElement < Mask = T > , { unsafe { core :: intrinsics :: simd :: simd_select (self . to_int () , true_values , false_values) } } # [doc = " Choose elements from two masks."] # [doc = ""] # [doc = " For each element in the mask, choose the corresponding element from `true_values` if"] # [doc = " that element mask is true, and `false_values` if that element mask is false."] # [doc = ""] # [doc = " # Examples"] # [doc = " ```"] # [doc = " # #![feature(portable_simd)]"] # [doc = " # use core::simd::Mask;"] # [doc = " let a = Mask::<i32, 4>::from_array([true, true, false, false]);"] # [doc = " let b = Mask::<i32, 4>::from_array([false, false, true, true]);"] # [doc = " let mask = Mask::<i32, 4>::from_array([true, false, false, true]);"] # [doc = " let c = mask.select_mask(a, b);"] # [doc = " assert_eq!(c.to_array(), [true, false, true, false]);"] # [doc = " ```"] # [inline] # [must_use = "method returns a new mask and does not mutate the original inputs"] pub fn select_mask (self , true_values : Self , false_values : Self) -> Self { self & true_values | ! self & false_values } }}}